                key = act["key"]
                if tx[conn] is not None:
                    cur = tx[conn].get(key, committed.get(key))
                else:
                    cur = committed.get(key)
                if cur is not None:
                    if tx[conn] is not None:
                        tx[conn][key] = None
                    else:
                        committed.pop(key, None)
                    if conn == "main":
                        changes_main += 1
                        total_main += 1
                    else:
                        changes_other += 1
                        total_other += 1
                    if trig:
                        log += 1
        # channel value
        if chan == "changes":
            ch = changes_main
        elif chan == "total_changes":
            ch = total_main
        else:
            ch = total_main + total_other
        return ch, len(committed), sum(committed.values())

    # filter candidates
    candidates = []
    for put_mode in ["ignore", "replace", "upsert"]:
        for trig in [False, True]:
            for chan in ["changes", "total_changes", "total_changes_both"]:
                ok = True
                for rec in hist:
                    ch, cc, cs = simulate(put_mode, trig, chan, rec["actions"])
                    obs = rec["observed"]
                    if ch != obs["channel"] or cc != obs["committed_count"] or cs != obs["committed_sum"]:
                        ok = False
                        break
                if ok:
                    candidates.append((put_mode, trig, chan))

    goal = context.get("goal")
    actions = context.get("actions", [])
    vals = set()
    for put_mode, trig, chan in candidates:
        ch, cc, cs = simulate(put_mode, trig, chan, actions)
        if goal == "channel":
            vals.add(ch)
        elif goal == "committed_count":
            vals.add(cc)
        elif goal == "committed_sum":
            vals.add(cs)
    if len(vals) == 1:
        return {"value": list(vals)[0], "unresolved": False}
    return {"value": None, "unresolved": True}

